const root="C:/Users/Blas_/Documents/Aplicacion de Pareja/flutter_client/assets/images/premium_3d_avatars/";
const ids=["mate_boy","keys_girl","market_dog","orange_cat","paper_plane_kid","star_girl","key_bird","tool_adult_man"];
const names=["curly brown haired young adult man with stubble and beige hoodie carrying mate","brown long wavy haired adult woman with gold hoop earrings and cream cardigan carrying keys","golden floppy eared puppy with sage bandana and orange heart patch","orange tabby kitten with sage bandana and peach heart patch","curly brown haired boy with peach hoodie and sage backpack","long curly dark haired girl with sage bow headband and peach sweater","round fluffy yellow bird with sage bandana","brown wavy haired adult man with stubble and sage apron over cream sweater"];
