text(await tools.exec_command({cmd:"Get-Content flutter_client/lib/features/dashboard/presentation/widgets/couple_home_widgets.dart -TotalCount 165; Get-Content flutter_client/lib/features/dashboard/presentation/screens/modes/home_couple_view.dart | Select-Object -Skip 510 -First 145; Get-Content flutter_client/test/couple_home_design_test.dart -TotalCount 370; rg -n 'assets/images|coupleHomeWelcomeTitle|coupleHomeCompleteTask' flutter_client/pubspec.yaml flutter_client/lib/l10n/app_es.arb flutter_client/lib/l10n/app_en.arb","max_output_tokens":8500}));

