const d=load("avatarDesign");
const jobs=[
{key:"portrait_orange_cat",prompt:"Create one production avatar portrait icon for HomeSync matching the provided orange tabby kitten reference identity and warm hand-painted watercolor storybook texture. Redesign from scratch specifically for a tiny 44 px circular task avatar: front facing face and very small hint of sage scarf, large clear kind green eyes, ears fully inside frame, symmetrical balanced silhouette, no grocery bag, no body, no text. A soft warm cream circular medallion behind the head, all artwork contained inside that perfect circle with 8% outer transparent margin. Thin subtle peach rim, no heavy shadow. High craft illustration, simplified detail readable small, cute and modern. Square canvas, actual transparent background outside circle. Reference is identity/style guidance, DO NOT just crop it.",refs:[d.root+"premium_orange_cat.webp"]},
{key:"duo_market_dog__orange_cat",prompt:"Create ONE original shared illustration for HomeSync's compact welcome hero, using the provided golden puppy and orange tabby kitten as exact character identity and warm watercolor storybook style references. Newly draw both as one coherent intimate cozy composition: seated nestled close, heads gently tilted toward one another, their paws together around a single tiny terracotta plant pot with a sage leafy sprout between them. Same sage bandanas with peach heart patches, preserve each face/species/colors. No grocery bags. Two complete distinct characters, roughly same head scale, grouped into one balanced low wide silhouette. The characters interact with shared prop, not two existing stickers next to each other. Premium cute, soft natural brushwork, warm cream and sage, friendly home companionship. No lettering, no card, no circle, no sticker white outline, no scene background, no floating decorations. Transparent background, centered artwork fully visible with 5% safe margin, landscape 3:2 composition.",refs:[d.root+"premium_market_dog.webp",d.root+"premium_orange_cat.webp"]}
];
d.jobs.push(...jobs);store("avatarDesign",d);
const work=Promise.allSettled(jobs.map(async j=>{const r=await tools.image_gen__imagegen({prompt:j.prompt,referenced_image_paths:j.refs,transparent_background:true});store(j.key,r);text({key:j.key,result:r});}));
await yield_control(); await work;

