const d=load("avatarDesign");
const portraitRef="C:/Users/Blas_/.codex/generated_images/01a10287-18b7-7180-9459-de1ef8ab8d9d/exec-e738ba21-82c4-4dad-b57b-145ef650af1e.png";
const jobs=d.ids.map((id,i)=>({key:`portrait_${id}`,refs:[d.root+`premium_${id}.webp`,portraitRef],prompt:`Create ONE newly drawn circular task avatar portrait of the ${d.names[i]}. Reference 1 defines ONLY the character identity. Reference 2 defines the EXACT circular icon family style, framing, soft cream background, peach thin rim and warm watercolor quality; do not include the cat from reference 2. Adapt character to this designed headshot family from scratch: face fills circle, slight shoulders, all hair/ears inside circle, face centered with large friendly clear eyes, simplify for 44 px display. Preserve recognizable hair, facial features, clothing color and accessories worn on head. Remove carried items, hands, bags, keys, cups, tools, notebooks. No full body. One circular medallion, 5% transparent safe margin all around, square canvas. True transparent background outside the circle, NO glow or shadow or white square, no text. Polished cute hand-painted storybook art matching references, not a crop.`})).filter(j=>j.key!=="portrait_orange_cat");
jobs.push({key:"duo_market_dog__orange_cat",refs:["C:/Users/Blas_/.codex/generated_images/01a10287-18b7-7180-9459-de1ef8ab8d9d/exec-2a44198a-720c-4bcd-8a12-1e951e60ad58.png"],prompt:"Edit this exact illustration ONLY to remove ALL blurred golden/orange glow, halo, ambient haze and shadow around the two characters and plant. Preserve the two characters, their poses, faces, watercolor texture, colors, shared plant and composition exactly. The entire area outside the crisp natural outer silhouette of puppy+kitten+plant must be 100% transparent alpha=0. No background color, no glow, no blur, no white outline. Keep 5% safe transparent margins, landscape canvas. This is a production transparent UI asset used on light AND dark backgrounds."});
d.jobs.push(...jobs);store("avatarDesign",d);
const work=Promise.allSettled(jobs.map(async j=>{const r=await tools.image_gen__imagegen({prompt:j.prompt,referenced_image_paths:j.refs,transparent_background:true});store(j.key,r);notify({ready:j.key,hint:r.output_hint});}));
await yield_control();await work;

