const d=load("avatarDesign");const ids=[...d.ids].sort();
const pairs=[];for(let i=0;i<ids.length;i++)for(let j=i;j<ids.length;j++)if(!(ids[i]==="market_dog"&&ids[j]==="orange_cat"))pairs.push([ids[i],ids[j]]);
store("duoPairs",pairs);
const jobs=pairs.slice(0,7).map(([a,b])=>{
const desc=id=>d.names[d.ids.indexOf(id)];
const animals=["market_dog","orange_cat","key_bird"];const bothAnimal=animals.includes(a)&&animals.includes(b);const mixed=animals.includes(a)!==animals.includes(b);
const pose=bothAnimal?"Nestled seated together, heads inclined inward, both paws or wings gently holding one shared small terracotta pot with a leafy sage sprout.":mixed?"The human crouches close beside the animal and both joyfully tend one small terracotta pot with a leafy sage sprout. Both faces prominent and equally readable.":"A close waist-up shared portrait, shoulders touching and heads gently inclined inward, both together holding one little terracotta pot with a leafy sage sprout.";
return {key:`duo_${a}__${b}`,refs:[...new Set([d.root+`premium_${a}.webp`,d.root+`premium_${b}.webp`])],prompt:`Create ONE original shared HomeSync welcome illustration starring EXACTLY TWO characters: ${desc(a)} AND ${desc(b)}. ${a===b?"Both users chose the SAME avatar: depict TWO separate recognizable instances of that exact character, different complementary poses; neither may be omitted.":""} References define each identity and warm watercolor storybook style. Redraw them into ONE cohesive cozy home-companionship composition: ${pose} Cute friendly happiness, NOT romantic gestures. Remove carried bags, cups, keys, notebooks, tools from references, keep clothing and recognizable features. Faces same scale. Shared plant in lower center, no props obscuring faces. Simplified elegant details readable at 132 x 100 px. Fully visible compact low wide silhouette centered with 6% safe margins. No card, frame, white sticker border, text, floating decorations. TRUE TRANSPARENT BACKGROUND outside crisp natural silhouettes, ALPHA ZERO outside subjects, absolutely NO glow, NO blurry halo, NO lighting haze, NO ground shadow. Landscape 3:2 canvas. Warm peach, cream and sage, high quality soft hand-painted watercolor.`};});
store("duoBatch1",jobs);
const work=Promise.allSettled(jobs.map(async j=>{const r=await tools.image_gen__imagegen({prompt:j.prompt,referenced_image_paths:j.refs,transparent_background:true});store(j.key,r);notify({ready:j.key,hint:r.output_hint});}));
await yield_control();await work;

